      ('Pre-facelift'::text, 'Estate'::text, 'CRBC'::text, 110::integer, 'MQ350'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'CRBC'::text, 110::integer, 'MQ350'::text, 'haldex_gen5'::text),
      ('Pre-facelift'::text, 'Hatchback 3-door'::text, 'CRBC'::text, 110::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'CRBC'::text, 110::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'CRBC'::text, 110::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 3-door'::text, 'CUNA'::text, 135::integer, 'MQ350'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'CUNA'::text, 135::integer, 'MQ350'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'CUNA'::text, 135::integer, 'MQ350'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 3-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Hatchback 5-door'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'CUNA'::text, 135::integer, 'DQ250'::text, null::text)
  )
insert into catalog_vehicle_configurations (phase_id, body_type_id, engine_id, unit_id, drivetrain_id)
select p.id, b.id, e.id, u.id, d.id
from configs c
join phase_lookup p on p.phase_label = c.phase_label
join body_lookup b on b.name = c.body_name
join engine_lookup e on e.code = c.engine_code and e.power_kw = c.engine_power_kw
join unit_lookup u on u.code = c.unit_code or c.unit_code = any(u.alt_codes)
left join dt_lookup d on d.code = c.dt_code
on conflict (
  phase_id, body_type_id, engine_id, unit_id,
  coalesce(drivetrain_id, '00000000-0000-0000-0000-000000000000'::uuid)
) do nothing;

-- ════════════════════════════════════════════════════════════
-- 8. TRIMS
--    7 row(s).
-- ════════════════════════════════════════════════════════════

insert into catalog_trims (phase_id, name, tier)
select p.id, v.name, v.tier
from (
  values
    ('Pre-facelift'::text, 'Reference'::text, 1::integer),
    ('Facelift'::text, 'Reference'::text, 1::integer),
    ('Pre-facelift'::text, 'Style'::text, 2::integer),
    ('Facelift'::text, 'Style'::text, 2::integer),
    ('Pre-facelift'::text, 'FR'::text, 3::integer),
    ('Facelift'::text, 'FR'::text, 3::integer),
    ('Facelift'::text, 'Xcellence'::text, 3::integer)
) as v(phase_label, name, tier)
join (
  select cp.id, cp.phase_label
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'SEAT' and cm.name = 'León' and cp.generation_code = '5F'
) as p on p.phase_label = v.phase_label
where not exists (
  select 1 from catalog_trims ct where ct.phase_id = p.id and ct.name = v.name
);

-- ════════════════════════════════════════════════════════════
-- 9. TRIM FEATURES
--    26 row(s).
-- ════════════════════════════════════════════════════════════

with trim_lookup as (
  select ct.id, cp.phase_label, ct.name
  from catalog_trims ct
  join catalog_phases cp on cp.id = ct.phase_id
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'SEAT' and cm.name = 'León' and cp.generation_code = '5F'
)
insert into catalog_trim_features (trim_id, feature, is_optional)
select tl.id, v.feature, v.is_optional
from (
  values
    ('Pre-facelift'::text, 'Reference'::text, 'Steel wheels'::text, false),
    ('Facelift'::text, 'Reference'::text, 'Steel wheels'::text, false),
    ('Pre-facelift'::text, 'Reference'::text, 'Manual air conditioning'::text, false),
    ('Facelift'::text, 'Reference'::text, 'Manual air conditioning'::text, false),
    ('Pre-facelift'::text, 'Reference'::text, '5-inch monochrome/basic touch display'::text, false),
    ('Facelift'::text, 'Reference'::text, '5-inch monochrome/basic touch display'::text, false),
    ('Pre-facelift'::text, 'Style'::text, 'Alloy wheels'::text, false),
    ('Facelift'::text, 'Style'::text, 'Alloy wheels'::text, false),
    ('Pre-facelift'::text, 'Style'::text, 'Dual-zone automatic climate control (Climatronic)'::text, false),
    ('Facelift'::text, 'Style'::text, 'Dual-zone automatic climate control (Climatronic)'::text, false),
    ('Pre-facelift'::text, 'Style'::text, 'Cruise control'::text, false),
    ('Facelift'::text, 'Style'::text, 'Cruise control'::text, false),
    ('Pre-facelift'::text, 'Style'::text, 'Leather multi-function steering wheel'::text, false),
    ('Facelift'::text, 'Style'::text, 'Leather multi-function steering wheel'::text, false),
    ('Pre-facelift'::text, 'FR'::text, 'Sport lowered suspension'::text, false),
    ('Facelift'::text, 'FR'::text, 'Sport lowered suspension'::text, false),
    ('Pre-facelift'::text, 'FR'::text, 'SEAT Drive Profile selector'::text, false),
    ('Facelift'::text, 'FR'::text, 'SEAT Drive Profile selector'::text, false),
    ('Pre-facelift'::text, 'FR'::text, 'Sport seats'::text, false),
    ('Facelift'::text, 'FR'::text, 'Sport seats'::text, false),
    ('Pre-facelift'::text, 'FR'::text, 'Aggressive bumpers and LED tail lights'::text, false),
    ('Facelift'::text, 'FR'::text, 'Aggressive bumpers and LED tail lights'::text, false),
    ('Facelift'::text, 'Xcellence'::text, 'Chrome trim'::text, false),
    ('Facelift'::text, 'Xcellence'::text, 'Kessy keyless entry'::text, false),
    ('Facelift'::text, 'Xcellence'::text, 'Specific upholstery'::text, false),
    ('Facelift'::text, 'Xcellence'::text, 'Ambient interior lighting'::text, false)
) as v(phase_label, trim_name, feature, is_optional)
join trim_lookup tl on tl.phase_label = v.phase_label and tl.name = v.trim_name
where not exists (
  select 1 from catalog_trim_features ctf where ctf.trim_id = tl.id and ctf.feature = v.feature
);

-- ════════════════════════════════════════════════════════════
-- 10. COMPONENT FAULTS
--    1 row(s).
-- ════════════════════════════════════════════════════════════

with
  engine_lookup as (
    select id, code, power_kw from catalog_engines
    where (code, power_kw) in (('CJXA', 206))
  ),
  engine_faults (target_code, target_power_kw, fault, severity) as (
    values
      ('CJXA'::text, 206::integer, 'Failure of the electrical turbocharger wastegate actuator (IHI IS38), causing limp mode and power loss.'::text, 'moderate'::text)
  )
insert into catalog_component_faults (component_type, engine_id, fault, severity)
select 'engine', e.id, f.fault, f.severity
from engine_faults f
join engine_lookup e on e.code = f.target_code and e.power_kw = f.target_power_kw
where not exists (
  select 1 from catalog_component_faults ccf where ccf.engine_id = e.id and ccf.fault = f.fault
);

-- ════════════════════════════════════════════════════════════
-- 11. DESTRUCTIVE — alt_codes UPDATE(s)
--    UPDATE of existing data: stays file-only, human-run, NOT executed here. Each guarded to fire only if the live value still matches what was seen at generation time, and to affect exactly 1 row.
-- ════════════════════════════════════════════════════════════

begin;

do $$
declare
  n integer;
begin
  update catalog_engines
  set alt_codes = '{CMBA}'
  where code = 'CZCA' and power_kw = 92 and alt_codes = '{}';
  get diagnostics n = row_count;
  if n <> 1 then
    raise exception 'Expected CZCA (92kW) alt_codes to be exactly {} and updated once, % affected — aborting.', n;
  end if;
end $$;

do $$
declare
  n integer;
begin
  update catalog_engines
  set alt_codes = '{CZEA}'
  where code = 'CZDA' and power_kw = 110 and alt_codes = '{}';
  get diagnostics n = row_count;
  if n <> 1 then
    raise exception 'Expected CZDA (110kW) alt_codes to be exactly {} and updated once, % affected — aborting.', n;
  end if;
end $$;

do $$
declare
  n integer;
begin
  update catalog_engines
  set alt_codes = '{CXXB}'
  where code = 'CRKB' and power_kw = 81 and alt_codes = '{}';
  get diagnostics n = row_count;
  if n <> 1 then
    raise exception 'Expected CRKB (81kW) alt_codes to be exactly {} and updated once, % affected — aborting.', n;
  end if;
end $$;

do $$
declare
  n integer;
begin
  update catalog_engines
  set alt_codes = '{CUPA}'
  where code = 'CUNA' and power_kw = 135 and alt_codes = '{}';
  get diagnostics n = row_count;
  if n <> 1 then
    raise exception 'Expected CUNA (135kW) alt_codes to be exactly {} and updated once, % affected — aborting.', n;
  end if;
end $$;

commit;

-- ════════════════════════════════════════════════════════════
-- 12. POST-CONDITION ASSERTIONS
--    Asserts exactly the expected phase and config counts for this generation_code exist live -- catches a silent guard false-positive (e.g. the phases-guard bug: matching another generation's same-labeled phase) instead of leaving it undetected.
-- ════════════════════════════════════════════════════════════

do $$
declare
  phase_n integer;
  config_n integer;
begin
  select count(*) into phase_n
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'SEAT' and cm.name = 'León' and cp.generation_code = '5F';
  if phase_n <> 2 then
    raise exception 'Expected 2 phase(s) for SEAT León (5F), found % -- a phase guard may have false-positived against another generation.', phase_n;
  end if;

  select count(*) into config_n
  from catalog_vehicle_configurations cvc
  join catalog_phases cp on cp.id = cvc.phase_id
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'SEAT' and cm.name = 'León' and cp.generation_code = '5F';
  if config_n <> 106 then
    raise exception 'Expected 106 config(s) for SEAT León (5F), found %.', config_n;
  end if;
end $$;
